typedef float rational_t;

class vector3d {
public:
    float x;
    float y;
    float z;

    vector3d() {}
    vector3d(const vector3d &other) : x(other.x), y(other.y), z(other.z) {}
    float length2() const { return x * x + y * y + z * z; }
};

inline vector3d operator-(const vector3d &left, const vector3d &right)
{
    return vector3d(left.x - right.x, left.y - right.y, left.z - right.z);
}

inline float dot(const vector3d &left, const vector3d &right)
{
    return left.x * right.x + left.y * right.y + left.z * right.z;
}

class ai_locomotion {
    char padding_to_start_pos[0x90];
    vector3d start_pos;
public:
    bool crossed_point(const vector3d test_point, const vector3d &cur_pos, rational_t radius, bool force_xz);
};

bool ai_locomotion::crossed_point(const vector3d test_point, const vector3d &cur_pos, rational_t radius, bool force_xz)
{
  if(radius < 0.0f)
    return(false);

  vector3d delta = test_point - cur_pos;
  vector3d move_delta = test_point - start_pos;

  if(force_xz || __builtin_fabsf(delta.y) < 1.0f)
  {
    move_delta.y = 0.0f;
    delta.y = 0.0f;
  }

  return(delta.length2() <= (radius*radius) || dot(delta, move_delta) < 0.0f);
}
